import torchimport cv2import numpy as npimport osimport globfrom torchvision import transformsimport torch.nn as nnclass PatchEmb(nn.Module):    def __init__(self, img_size=224, patch_size=16, in_chans=3, embed_dim=192):        super().__init__()        self.num_patches = (img_size // patch_size) ** 2        self.proj = nn.Conv2d(in_chans, embed_dim, kernel_size=patch_size, stride=patch_size)    def forward(self, x):        return self.proj(x).flatten(2).transpose(1, 2)class Attention(nn.Module):    def __init__(self, dim, num_heads=6, qkv_bias=True, attn_drop=0., proj_drop=0.):        super().__init__()        self.num_heads = num_heads        self.head_dim = dim // num_heads        self.scale = self.head_dim ** -0.5        self.qkv = nn.Linear(dim, dim * 3, bias=qkv_bias)        self.attn_drop = nn.Dropout(attn_drop)        self.proj = nn.Linear(dim, dim)        self.proj_drop = nn.Dropout(proj_drop)    def forward(self, x):        B, N, C = x.shape        qkv = self.qkv(x).reshape(B, N, 3, self.num_heads, self.head_dim).permute(2, 0, 3, 1, 4)        q, k, v = qkv[0], qkv[1], qkv[2]        attn = (q @ k.transpose(-2, -1)) * self.scale        attn = attn.softmax(dim=-1)        attn = self.attn_drop(attn)        x = (attn @ v).transpose(1, 2).reshape(B, N, C)        return self.proj_drop(self.proj(x)), attnclass MLP(nn.Module):    def __init__(self, in_features, hidden_features, drop=0.):        super().__init__()        self.fc1 = nn.Linear(in_features, hidden_features)        self.act = nn.GELU()        self.fc2 = nn.Linear(hidden_features, in_features)        self.drop = nn.Dropout(drop)    def forward(self, x):        return self.drop(self.fc2(self.drop(self.act(self.fc1(x)))))class Block(nn.Module):    def __init__(self, dim, num_heads, mlp_ratio=2.0, drop=0.):        super().__init__()        self.norm1 = nn.LayerNorm(dim)        self.attn = Attention(dim, num_heads, proj_drop=drop)        self.norm2 = nn.LayerNorm(dim)        self.mlp = MLP(dim, int(dim * mlp_ratio), drop)    def forward(self, x):        a_out, a_map = self.attn(self.norm1(x))        x = x + a_out        return x + self.mlp(self.norm2(x)), a_mapclass ViT(nn.Module):    def __init__(self, img_size=224, patch_size=16, in_chans=3, num_classes=10, embed_dim=192, depth=8, num_heads=6,                 mlp_ratio=2.0, drop_rate=0.):        super().__init__()        self.patch_embed = PatchEmb(img_size, patch_size, in_chans, embed_dim)        num_patches = self.patch_embed.num_patches        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))        self.pos_embed = nn.Parameter(torch.zeros(1, num_patches + 1, embed_dim))        self.pos_drop = nn.Dropout(drop_rate)        self.blocks = nn.ModuleList([Block(embed_dim, num_heads, mlp_ratio, drop_rate) for _ in range(depth)])        self.norm = nn.LayerNorm(embed_dim)        self.head = nn.Linear(embed_dim, num_classes)    def forward(self, x):        B = x.shape[0]        x = self.patch_embed(x)        cls = self.cls_token.expand(B, -1, -1)        x = torch.cat((cls, x), dim=1)        x = x + self.pos_embed        x = self.pos_drop(x)        attn = None        for blk in self.blocks:            x, attn = blk(x)        return self.head(self.norm(x)[:, 0]), attnDEVICE = 'cuda' if torch.cuda.is_available() else 'cpu'MODEL_PATH = '../vit_driver_split_epoch22_acc77.85.pth'IMG_DIR = '../sample'LABELS = ["Safe Driving", "Texting - Right", "Talking - Right", "Texting - Left", "Talking - Left", "Operating Radio",          "Drinking", "Reaching Behind", "Hair/Makeup", "Talking to Passenger"]print("loading...")model = ViT()if os.path.exists(MODEL_PATH):    ckpt = torch.load(MODEL_PATH, map_location=DEVICE)    model.load_state_dict(ckpt['model_state_dict'] if 'model_state_dict' in ckpt else ckpt)else:    exit("no model")model.to(DEVICE)model.eval()tfms = transforms.Compose([transforms.ToPILImage(), transforms.Resize((224, 224)), transforms.ToTensor(),                           transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])])def get_vis(img, attn, ps=16):    a = attn.mean(0)[0, 1:]    g = 224 // ps    a = a.reshape(g, g).detach().cpu().numpy()    a = (a - a.min()) / (a.max() - a.min())    hm = cv2.applyColorMap(np.uint8(255 * cv2.resize(a, (img.shape[1], img.shape[0]))), cv2.COLORMAP_JET)    return cv2.addWeighted(img, 0.6, hm, 0.4, 0)files = []for e in ['*.jpg', '*.jpeg', '*.png']:    files.extend(glob.glob(os.path.join(IMG_DIR, e)))print(f"found {len(files)} images")for f in files:    img = cv2.imread(f)    if img is None: continue    t = tfms(cv2.cvtColor(img, cv2.COLOR_BGR2RGB)).unsqueeze(0).to(DEVICE)    with torch.no_grad():        out, att = model(t)        _, pred = torch.max(out, 1)    res = get_vis(img, att[0])    txt = LABELS[pred.item()]    c = (0, 255, 0) if pred.item() == 0 else (0, 0, 255)    cv2.rectangle(res, (0, 0), (450, 50), (0, 0, 0), -1)    cv2.putText(res, txt, (10, 35), cv2.FONT_HERSHEY_SIMPLEX, 1.0, c, 2)    cv2.imshow('vis', res)    if cv2.waitKey(0) == ord('q'): breakcv2.destroyAllWindows()